import numpy as np

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-07
def _positive_integer(name, value):
    if isinstance(value, (bool, np.bool_)) or not isinstance(value, (int, np.integer)) or value < 1:
        raise ValueError(f"{name} must be a positive integer")
    return int(value)

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-09
def multioutput_target(df, horizon=10, dropna=True):
    horizon = _positive_integer("horizon", horizon)
    df = df.copy()
    for col in df.columns:
        for h in range(1, 1 + horizon):
            df[f"{col}_t+{h}"] = df[col].shift(-h)
    return df.dropna() if dropna else df

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-11
def onestep_target(df, dropna=True):
    return multioutput_target(df, horizon=1, dropna=dropna)

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-13
def step_ahead_target(df, step=5, dropna=True):
    step = _positive_integer("step", step)
    df = df.copy()
    for col in df.columns:
        df[f"{col}_t+{step}"] = df[col].shift(-step)
    return df.dropna() if dropna else df

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-15
def fractional_weights(d, lags):
    """The first lags binomial coefficients of the operator (1-B)^d."""
    lags = _positive_integer("lags", lags)
    d = float(d)
    if not np.isfinite(d):
        raise ValueError("d must be finite")
    weights = [1.0]
    for k in range(1, lags):
        weights.append(-weights[-1] * (d - k + 1) / k)
    return np.asarray(weights).reshape(-1, 1)

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-17
def fractional_differencing(series, order: float, fractional_coefficients: int, *, lag=1):
    """Apply a finite binomial approximation to (1-B^lag)^order.

    Discard only the initial (fractional_coefficients-1)*lag rows that do not
    have a full history. Missing observations inside the series propagate.
    """
    count = _positive_integer("fractional_coefficients", fractional_coefficients)
    lag = _positive_integer("lag", lag)
    order = float(order)
    if not np.isfinite(order) or order < 0:
        raise ValueError("order must be finite and nonnegative")
    if order == 0:
        return series.copy()
    weights = fractional_weights(order, count)[:, 0]
    result = sum(weights[k] * series.shift(k * lag) for k in range(count))
    return result.iloc[(count - 1) * lag:]

# %% ../notebooks/05_target_engineering.ipynb #05_target_engineerin-19
def differencing(series, order=1, fractional_coefficients=10, *, lag=1):
    """Apply repeated lag differences; order is not a lag distance.

    order=2 means y[t]-2*y[t-lag]+y[t-2*lag]. For a seasonal first difference
    use order=1, lag=period. Order zero returns a copy unchanged. Noninteger
    orders use the explicitly truncated fractional approximation.
    """
    lag = _positive_integer("lag", lag)
    if isinstance(order, (bool, np.bool_)):
        raise ValueError("order must be a finite nonnegative number")
    order = float(order)
    if not np.isfinite(order) or order < 0:
        raise ValueError("order must be a finite nonnegative number")
    if order.is_integer():
        result = series.copy()
        for _ in range(int(order)):
            result = result.diff(periods=lag)
        return result.iloc[int(order) * lag:]
    return fractional_differencing(series, order, fractional_coefficients, lag=lag)
